#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <errno.h>
#include <time.h>
#include <pthread.h>

#define MAX_UPLOAD_SIZE (10 * 1024 * 1024)
#define STAGING_DIR "/var/lib/monitor/staging"
#define PROCESSED_DIR "/var/lib/monitor/processed"
#define LOG_FILE "/var/log/monitor/agent.log"

typedef struct {
    char client_id[64];
    size_t payload_size;
    unsigned char *payload;
    time_t received_at;
} upload_record_t;

typedef struct {
    int fd;
    char path[256];
    mode_t original_umask;
} staging_context_t;

static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

static void agent_log(const char *level, const char *fmt, ...) {
    va_list args;
    pthread_mutex_lock(&log_mutex);
    FILE *lf = fopen(LOG_FILE, "a");
    if (lf) {
        time_t now = time(NULL);
        char timebuf[32];
        strftime(timebuf, sizeof(timebuf), "%Y-%m-%d %H:%M:%S", localtime(&now));
        fprintf(lf, "[%s] %s: ", timebuf, level);
        va_start(args, fmt);
        vfprintf(lf, fmt, args);
        va_end(args);
        fprintf(lf, "\n");
        fclose(lf);
    }
    pthread_mutex_unlock(&log_mutex);
}

static int validate_client_id(const char *client_id) {
    if (!client_id || strlen(client_id) == 0 || strlen(client_id) > 63)
        return -1;
    for (const char *p = client_id; *p; p++) {
        if (!((*p >= 'a' && *p <= 'z') || (*p >= 'A' && *p <= 'Z') ||
              (*p >= '0' && *p <= '9') || *p == '-' || *p == '_'))
            return -1;
    }
    return 0;
}

static int create_staging_file(staging_context_t *ctx, const char *client_id) {
    char template[256];
    int ret;

    ret = snprintf(template, sizeof(template), "%s/%s_XXXXXX", STAGING_DIR, client_id);
    if (ret < 0 || (size_t)ret >= sizeof(template))
        return -1;

    /* Set restrictive umask before creating temp file */
    ctx->original_umask = umask(0177);

    ctx->fd = mkstemp(template);
    if (ctx->fd < 0) {
        umask(ctx->original_umask);
        agent_log("ERROR", "mkstemp failed for client %s: %s", client_id, strerror(errno));
        return -1;
    }

    strncpy(ctx->path, template, sizeof(ctx->path) - 1);
    ctx->path[sizeof(ctx->path) - 1] = '\0';

    umask(ctx->original_umask);
    return 0;
}

static int write_staging_data(staging_context_t *ctx, const unsigned char *data, size_t len) {
    size_t written = 0;
    while (written < len) {
        ssize_t n = write(ctx->fd, data + written, len - written);
        if (n < 0) {
            if (errno == EINTR) continue;
            return -1;
        }
        written += n;
    }
    return 0;
}

static int finalize_staging(staging_context_t *ctx, const char *client_id) {
    char final_path[256];
    struct timespec ts;

    if (fsync(ctx->fd) < 0) {
        agent_log("ERROR", "fsync failed: %s", strerror(errno));
        goto cleanup_err;
    }
    close(ctx->fd);
    ctx->fd = -1;

    clock_gettime(CLOCK_REALTIME, &ts);
    snprintf(final_path, sizeof(final_path), "%s/%s_%ld_%ld.dat",
             PROCESSED_DIR, client_id, (long)ts.tv_sec, (long)ts.tv_nsec);

    /* Verify file ownership before moving to processed directory */
    struct stat st;
    if (stat(ctx->path, &st) < 0) {
        agent_log("ERROR", "stat failed on staging file: %s", strerror(errno));
        goto cleanup_err;
    }

    if (st.st_uid != getuid()) {
        agent_log("ERROR", "staging file ownership mismatch");
        goto cleanup_err;
    }

    /* TOCTOU window: between stat() and rename(), the file at ctx->path
       could be replaced via symlink if staging dir permissions allow */
    if (rename(ctx->path, final_path) < 0) {
        agent_log("ERROR", "rename failed: %s", strerror(errno));
        goto cleanup_err;
    }

    agent_log("INFO", "Upload from %s finalized to %s", client_id, final_path);
    return 0;

cleanup_err:
    if (ctx->fd >= 0) close(ctx->fd);
    unlink(ctx->path);
    return -1;
}

int process_upload(const char *client_id, const unsigned char *data, size_t data_len) {
    staging_context_t ctx = { .fd = -1 };

    if (validate_client_id(client_id) < 0) {
        agent_log("WARN", "Invalid client_id rejected");
        return -1;
    }

    if (data_len == 0 || data_len > MAX_UPLOAD_SIZE) {
        agent_log("WARN", "Invalid payload size: %zu", data_len);
        return -1;
    }

    if (create_staging_file(&ctx, client_id) < 0)
        return -1;

    if (write_staging_data(&ctx, data, data_len) < 0) {
        agent_log("ERROR", "Write failed for client %s", client_id);
        close(ctx.fd);
        unlink(ctx.path);
        return -1;
    }

    return finalize_staging(&ctx, client_id);
}

int main(int argc, char *argv[]) {
    /* Daemon initialization would go here */
    agent_log("INFO", "Monitor agent starting");

    /* Example: process a test upload */
    const char *test_data = "sample monitoring payload";
    process_upload("sensor-node-01", (const unsigned char *)test_data, strlen(test_data));

    return 0;
}
